-- ============================================================
-- Makams Ops — import the HR interview workbook into Prospectives
-- 465 people, generated from "926283f4-Interview_Candidate_Data.xlsx"
-- Re-running is safe: a CV number that is already there is skipped.
-- ============================================================

begin;

create temporary table _import (
  cv_no text,
  full_name text,
  division text,
  department text,
  designation text,
  area text,
  contact text,
  contact2 text,
  email text,
  reference text,
  test_score text,
  source text,
  status text,
  stage_mail text,
  stage_manager text,
  stage_hr text,
  stage_final text,
  comment text,
  last_salary numeric,
  expected_inhand numeric,
  old_inhand numeric,
  inhand_monthly numeric,
  gross_monthly numeric,
  ctc_annual numeric,
  doj date,
  emp_code text,
  created_at date
) on commit drop;


select cv_no, full_name, division, department, designation, area, contact, contact2, email, reference, test_score, source, status, stage_mail, stage_manager, stage_hr, stage_final, comment, last_salary, expected_inhand, old_inhand, inhand_monthly, gross_monthly, ctc_annual, doj, emp_code, created_at from _import i
 where not exists (select 1 from public.prospectives p where p.cv_no = i.cv_no);

-- warn about CV numbers that were already taken by someone else
do $$
declare v_clash int;
begin
  select count(*) into v_clash from _import i
    join public.prospectives p on p.cv_no = i.cv_no
   where p.full_name is distinct from i.full_name;
  if v_clash > 0 then
    raise notice '% CV numbers were already on the table under a different name and were NOT imported — check them', v_clash;
  end if;
end $$;

-- carry on numbering after the highest CV number that now exists
select setval('public.prospective_cv_seq',
  greatest((select coalesce(max(nullif(regexp_replace(cv_no, '\D', '', 'g'), ''))::bigint, 0) from public.prospectives), 1), true);

commit;

select 'Imported. prospectives=' || (select count(*) from public.prospectives)
  || ', next CV no. = MI' || lpad((last_value + 1)::text, 5, '0') as result
  from public.prospective_cv_seq;
